def main():
    if not TARGET.exists():
        raise SystemExit(f"대상 파일이 없습니다: {TARGET}")

    txt = TARGET.read_text(encoding="utf-8")

    # Clean up previously injected JS blocks from prior attempts.
    patterns = [
        r'\n?<script id="signature-ko-translation-script">[\s\S]*?</script>\n?',
        r'\n?<script id="signature-ko-catalogfull-script">[\s\S]*?</script>\n?',
        r'\n?<script id="signature-ko-dedupe-bodyonly-script">[\s\S]*?</script>\n?',
    ]
    cleaned = txt
    for pat in patterns:
        cleaned = re.sub(pat, "\n", cleaned, flags=re.MULTILINE)

    shutil.copy2(TARGET, BACKUP)
    cleaned = cleaned.rstrip() + "\n\n" + JS_BLOCK.strip() + "\n"
    TARGET.write_text(cleaned, encoding="utf-8")

    print("적용 완료:", TARGET)
    print("백업 생성:", BACKUP)
    print("이전 JS 보조설명 블록 정리 후 body-only 중복 제거 버전으로 교체했습니다.")

if __name__ == "__main__":
    main()
